type ledger struct {
	mu    sync.Mutex
	file  *os.File
	total int
}

func main() {
	addr := flag.String("addr", ":9000", "listen address")
	path := flag.String("ledger", "data/ledger.log", "ledger file")
	flag.Parse()
	l, err := open(*path)
	if err != nil {
		log.Fatal(err)
	}
	ln, err := net.Listen("tcp", *addr)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("ledger total %d\n", l.total)
	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Fatal(err)
		}
		go l.serve(conn)
	}
}

func open(path string) (*ledger, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return nil, err
	}
	total, complete := replay(data)
	assert.Sometimes(complete < len(data), "recovery dropped a partial entry", map[string]any{"bytes": len(data) - complete})
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := f.Truncate(int64(complete)); err != nil {
		return nil, err
	}
	if _, err := f.Seek(int64(complete), 0); err != nil {
		return nil, err
	}
	if err := f.Sync(); err != nil {
		return nil, err
	}
	if err := syncDir(filepath.Dir(path)); err != nil {
		return nil, err
	}
	return &ledger{file: f, total: total}, nil
}

func replay(data []byte) (int, int) {
	total, complete := 0, 0
	for {
		i := strings.IndexByte(string(data[complete:]), '\n')
		if i < 0 {
			return total, complete
		}
		n, err := strconv.Atoi(string(data[complete : complete+i]))
		if err != nil {
			return total, complete
		}
		total += n
		complete += i + 1
	}
}

func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}

